'use client';

import * as React from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import { cn } from '../lib/utils';
import { Button } from './Button';

export interface ModalProps {
  open: boolean;
  onClose: () => void;
  title?: string;
  description?: string;
  children: React.ReactNode;
  size?: 'sm' | 'md' | 'lg' | 'xl' | 'full';
  variant?: 'default' | 'confirm' | 'form';
  footer?: React.ReactNode;
  closeOnOverlayClick?: boolean;
  closeOnEscape?: boolean;
  className?: string;
}

const sizeClasses = {
  sm: 'max-w-md',
  md: 'max-w-2xl',
  lg: 'max-w-4xl',
  xl: 'max-w-6xl',
  full: 'max-w-[90vw]',
};

export const Modal = React.forwardRef<HTMLDivElement, ModalProps>(
  ({ open, onClose, title, description, children, size = 'md', variant = 'default', footer, closeOnOverlayClick = true, closeOnEscape = true, className }, ref) => {
    const modalRef = React.useRef<HTMLDivElement>(null);
    const previousActiveElement = React.useRef<HTMLElement | null>(null);

    React.useEffect(() => {
      if (open) {
        previousActiveElement.current = document.activeElement as HTMLElement;
        document.body.style.overflow = 'hidden';
        modalRef.current?.focus();
        
        const handleKeyDown = (e: KeyboardEvent) => {
          if (e.key === 'Escape' && closeOnEscape) {
            onClose();
          }
          if (e.key === 'Tab') {
            const focusableElements = modalRef.current?.querySelectorAll(
              'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
            );
            if (!focusableElements || focusableElements.length === 0) return;
            
            const firstElement = focusableElements[0] as HTMLElement;
            const lastElement = focusableElements[focusableElements.length - 1] as HTMLElement;
            
            if (e.shiftKey && document.activeElement === firstElement) {
              e.preventDefault();
              lastElement.focus();
            } else if (!e.shiftKey && document.activeElement === lastElement) {
              e.preventDefault();
              firstElement.focus();
            }
          }
        };
        
        document.addEventListener('keydown', handleKeyDown);
        return () => {
          document.removeEventListener('keydown', handleKeyDown);
          document.body.style.overflow = '';
          previousActiveElement.current?.focus();
        };
      }
    }, [open, closeOnEscape, onClose]);

    if (!open) return null;

    const modalContent = (
      <div
        className={cn(
          'fixed inset-0 z-[400] flex items-center justify-center p-4',
          className
        )}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? 'modal-title' : undefined}
        aria-describedby={description ? 'modal-description' : undefined}
      >
        <div
          className="fixed inset-0 bg-overlay animate-fade-in"
          onClick={closeOnOverlayClick ? onClose : undefined}
          aria-hidden="true"
        />
        <div
          ref={modalRef}
          tabIndex={-1}
          className={cn(
            'relative w-full bg-surface rounded-xl shadow-2xl animate-scale-in',
            sizeClasses[size],
            variant === 'confirm' && 'border-l-4 border-danger',
            variant === 'form' && 'max-h-[85vh] overflow-y-auto'
          )}
        >
          {(title || footer) && (
            <div className="flex items-start justify-between px-6 py-4 border-b border-border">
              <div>
                {title && (
                  <h2 id="modal-title" className="text-lg font-semibold text-text">
                    {title}
                  </h2>
                )}
                {description && (
                  <p id="modal-description" className="mt-1 text-sm text-text-muted">
                    {description}
                  </p>
                )}
              </div>
              <Button
                variant="ghost"
                size="icon"
                onClick={onClose}
                aria-label="Close modal"
                className="shrink-0"
              >
                <X className="h-5 w-5" />
              </Button>
            </div>
          )}
          <div className={cn('px-6 py-4', variant === 'form' ? 'pb-0' : '')}>
            {children}
          </div>
          {footer && (
            <div className="flex items-center justify-end gap-2 px-6 py-4 border-t border-border">
              {footer}
            </div>
          )}
        </div>
      </div>
    );

    if (typeof window === 'undefined') return null;
    return createPortal(modalContent, document.body);
  }
);

Modal.displayName = 'Modal';

export interface ConfirmModalProps {
  open: boolean;
  onClose: () => void;
  onConfirm: () => void;
  title: string;
  description: string;
  confirmLabel?: string;
  cancelLabel?: string;
  variant?: 'danger' | 'primary';
  loading?: boolean;
}

export function ConfirmModal({
  open,
  onClose,
  onConfirm,
  title,
  description,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  variant = 'danger',
  loading = false,
}: ConfirmModalProps) {
  return (
    <Modal open={open} onClose={onClose} size="sm" variant="confirm" title={title} description={description}>
      <div className="flex justify-end gap-2 pt-2">
        <Button variant="ghost" onClick={onClose} disabled={loading}>
          {cancelLabel}
        </Button>
        <Button variant={variant} onClick={onConfirm} loading={loading}>
          {confirmLabel}
        </Button>
      </div>
    </Modal>
  );
}

export interface AlertModalProps {
  open: boolean;
  onClose: () => void;
  title: string;
  description: string;
  label?: string;
}

export function AlertModal({ open, onClose, title, description, label = 'OK' }: AlertModalProps) {
  return (
    <Modal open={open} onClose={onClose} size="sm" title={title} description={description}>
      <div className="flex justify-end pt-2">
        <Button variant="primary" onClick={onClose}>
          {label}
        </Button>
      </div>
    </Modal>
  );
}